CREATE OR REPLACE FUNCTION "public"."claim_booking_email_dispatch"("p_booking_kind" "text", "p_booking_reference" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  current_status text;
  current_attempts integer;
  current_lock timestamptz;
begin
  if p_booking_kind not in ('service', 'resource')
     or p_booking_reference is null
     or length(p_booking_reference) < 8
     or length(p_booking_reference) > 100 then
    return false;
  end if;

  insert into public.booking_email_dispatches (
    booking_kind,
    booking_reference,
    status,
    attempts,
    locked_until
  )
  values (
    p_booking_kind,
    p_booking_reference,
    'processing',
    1,
    now() + interval '5 minutes'
  )
  on conflict (booking_kind, booking_reference) do nothing;

  if found then
    return true;
  end if;

  select status, attempts, locked_until
    into current_status, current_attempts, current_lock
  from public.booking_email_dispatches
  where booking_kind = p_booking_kind
    and booking_reference = p_booking_reference
  for update;

  if current_status = 'sent'
     or current_attempts >= 3
     or (current_lock is not null and current_lock > now()) then
    return false;
  end if;

  update public.booking_email_dispatches
  set
    status = 'processing',
    attempts = attempts + 1,
    locked_until = now() + interval '5 minutes',
    last_error = null,
    updated_at = now()
  where booking_kind = p_booking_kind
    and booking_reference = p_booking_reference;

  return true;
end;
$$;


ALTER FUNCTION "public"."claim_booking_email_dispatch"("p_booking_kind" "text", "p_booking_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_booking_email_rate_limit"("p_ip_hash" "text", "p_limit" integer DEFAULT 10, "p_window_seconds" integer DEFAULT 600) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  recent_attempts integer;
  safe_limit integer := greatest(1, least(coalesce(p_limit, 10), 100));
  safe_window integer := greatest(60, least(coalesce(p_window_seconds, 600), 86400));
begin
  if p_ip_hash is null or length(p_ip_hash) <> 64 then
    return false;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_ip_hash, 0));

  delete from public.booking_email_rate_limit_attempts
  where ip_hash = p_ip_hash
    and created_at < now() - interval '1 day';

  select count(*)::integer
    into recent_attempts
  from public.booking_email_rate_limit_attempts
  where ip_hash = p_ip_hash
    and created_at >= now() - make_interval(secs => safe_window);

  if recent_attempts >= safe_limit then
    return false;
  end if;

  insert into public.booking_email_rate_limit_attempts (ip_hash)
  values (p_ip_hash);

  return true;
end;
$$;


ALTER FUNCTION "public"."claim_booking_email_rate_limit"("p_ip_hash" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_service_booked_times_for_date"(
  "selected_date" "date",
  "selected_specialist_id" "uuid" DEFAULT NULL,
  "selected_option_id" "uuid" DEFAULT NULL,
  "selected_package_id" "uuid" DEFAULT NULL
) RETURNS TABLE("booking_time" time without time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select distinct generated_hour::time
  from public.service_bookings b
  cross join lateral generate_series(
    date_trunc('hour', b.booking_date + b.booking_time),
    date_trunc('hour', b.booking_date + b.booking_time)
      + ((greatest(coalesce(b.duration_hours, 1), 1) - 1) * interval '1 hour'),
    interval '1 hour'
  ) as generated_hour
  where b.booking_date = selected_date
    and coalesce(b.specialist_id::text, b.service_option_id::text, b.package_id::text) =
        coalesce(selected_specialist_id::text, selected_option_id::text, selected_package_id::text)
    and lower(coalesce(b.status, 'pending')) not in
      ('cancelled', 'canceled', 'deleted', 'rejected')
  order by generated_hour::time;
$$;


ALTER FUNCTION "public"."get_service_booked_times_for_date"("date", "uuid", "uuid", "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_resource_booked_times_for_date"("selected_date" "date") RETURNS TABLE("booking_time" time without time zone)
    LANGUAGE "sql" STABLE
    AS $$
  select resource_bookings.booking_time
  from resource_bookings
  where resource_bookings.booking_date = selected_date
    and resource_bookings.status <> 'cancelled'
  order by resource_bookings.booking_time;
$$;


ALTER FUNCTION "public"."get_resource_booked_times_for_date"("selected_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (
    id,
    name,
    phone,
    email,
    avatar_url,
    role
  )
  values (
    new.id,

    coalesce(
      nullif(new.raw_user_meta_data->>'full_name', ''),
      nullif(new.raw_user_meta_data->>'name', ''),
      split_part(new.email, '@', 1),
      'Клиент'
    ),

    coalesce(
      nullif(new.raw_user_meta_data->>'phone', ''),
      nullif(new.phone, ''),
      ''
    ),

    new.email,

    coalesce(
      nullif(new.raw_user_meta_data->>'avatar_url', ''),
      nullif(new.raw_user_meta_data->>'picture', '')
    ),

    'client'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


