CREATE POLICY "Public can read active service catalog"
ON "public"."service_catalog_items" FOR SELECT TO "anon", "authenticated"
USING ("is_active" = true OR "public"."is_admin"("auth"."uid"()));

CREATE POLICY "Admins can manage service catalog"
ON "public"."service_catalog_items" FOR ALL TO "authenticated"
USING ("public"."is_admin"("auth"."uid"()))
WITH CHECK ("public"."is_admin"("auth"."uid"()));

