-- OneStudio OS booking security hardening.
-- Applies after the imported prototype schema and removes all public access to PII.

create or replace function public.is_admin(user_id uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = user_id and role = 'admin'
  );
$$;

alter table public.service_bookings drop constraint if exists service_bookings_language_check;
alter table public.resource_bookings drop constraint if exists resource_bookings_language_check;
alter table public.client_galleries drop constraint if exists client_galleries_language_check;
alter table public.service_bookings add constraint service_bookings_language_code_check
  check (language ~ '^[a-z]{2,3}(-[a-z]{2})?$');
alter table public.resource_bookings add constraint resource_bookings_language_code_check
  check (language ~ '^[a-z]{2,3}(-[a-z]{2})?$');
alter table public.client_galleries add constraint client_galleries_language_code_check
  check (language ~ '^[a-z]{2,3}(-[a-z]{2})?$');

revoke all on function public.is_admin(uuid) from public;
grant execute on function public.is_admin(uuid) to authenticated, service_role;

-- Remove permissive prototype policies.
drop policy if exists "Admins can delete bookings" on public.service_bookings;
drop policy if exists "Admins can delete resource bookings" on public.resource_bookings;
drop policy if exists "Admins can read resource bookings" on public.resource_bookings;
drop policy if exists "Admins can update resource bookings" on public.resource_bookings;
drop policy if exists "Allow public booking insert" on public.service_bookings;
drop policy if exists "Anyone can create resource bookings" on public.resource_bookings;
drop policy if exists "Anyone can read resource booked slots" on public.resource_bookings;
drop policy if exists "Public can create bookings" on public.service_bookings;
drop policy if exists "Users can create their own bookings" on public.service_bookings;
drop policy if exists "Users can update their own bookings" on public.service_bookings;
drop policy if exists "Authenticated can edit site contacts" on public.site_contacts;
drop policy if exists "Authenticated users can manage learning extra blocks" on public.learning_extra_blocks;
drop policy if exists "Admins can manage portfolio categories" on public.portfolio_categories;
drop policy if exists "Admins can manage portfolio images" on public.portfolio_images;
drop policy if exists "Anyone can add portfolio likes" on public.portfolio_likes;
drop policy if exists "Anyone can read portfolio likes" on public.portfolio_likes;
drop policy if exists "Anyone can remove own browser like" on public.portfolio_likes;
drop policy if exists "Public can read service_options" on public.service_options;
drop policy if exists "Public can read packages" on public.packages;
drop policy if exists "Public can read team" on public.team;
drop policy if exists "Public can read site portfolio items" on public.site_portfolio_items;
drop policy if exists "Public can read visible learning extra blocks" on public.learning_extra_blocks;
drop policy if exists "Public can read visible page blocks" on public.page_blocks;
drop policy if exists "Public read active learning benefits" on public.learning_benefits;
drop policy if exists "Public read active learning programs" on public.learning_programs;

-- Clients may edit profile presentation fields, never role/email/identity fields.
revoke update on public.profiles from authenticated;
grant update (name, phone, avatar_url) on public.profiles to authenticated;

-- Admin writes are checked by the database for every protected table.
create policy "Admins delete bookings" on public.service_bookings
for delete to authenticated using (public.is_admin());
create policy "Admins insert bookings" on public.service_bookings
for insert to authenticated with check (public.is_admin());
create policy "Admins delete resource bookings" on public.resource_bookings
for delete to authenticated using (public.is_admin());
create policy "Admins insert resource bookings" on public.resource_bookings
for insert to authenticated with check (public.is_admin());
create policy "Admins read resource bookings" on public.resource_bookings
for select to authenticated using (public.is_admin());
create policy "Admins update resource bookings" on public.resource_bookings
for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Admins manage site contacts" on public.site_contacts
for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Admins manage learning extra blocks" on public.learning_extra_blocks
to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Admins manage portfolio categories secure" on public.portfolio_categories
to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Admins manage portfolio images secure" on public.portfolio_images
to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "Public reads active service_options secure" on public.service_options
for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "Public reads active packages secure" on public.packages
for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "Public reads active team secure" on public.team
for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "Public reads active site portfolio secure" on public.site_portfolio_items
for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "Public reads visible learning blocks secure" on public.learning_extra_blocks
for select to anon, authenticated using (is_visible = true or public.is_admin());
create policy "Public reads visible page blocks secure" on public.page_blocks
for select to anon, authenticated using (is_visible = true or public.is_admin());
create policy "Public reads active learning benefits secure" on public.learning_benefits
for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "Public reads active learning programs secure" on public.learning_programs
for select to anon, authenticated using (is_active = true or public.is_admin());

create or replace function public.get_portfolio_like_state(p_image_ids text[], p_visitor_id uuid)
returns table (image_id text, like_count bigint, liked boolean)
language sql
stable
security definer
set search_path = public
as $$
  select requested.image_id,
         count(l.id) as like_count,
         coalesce(bool_or(l.visitor_id = p_visitor_id), false) as liked
  from unnest(p_image_ids[1:200]) requested(image_id)
  left join public.portfolio_likes l on l.image_id = requested.image_id
  group by requested.image_id;
$$;

create or replace function public.set_portfolio_like(p_image_id text, p_visitor_id uuid, p_liked boolean)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  if length(coalesce(p_image_id, '')) not between 1 and 200 or p_visitor_id is null then
    raise exception 'invalid_like_data' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('like:' || p_image_id || ':' || p_visitor_id, 0));
  if p_liked then
    insert into public.portfolio_likes (image_id, visitor_id, user_id)
    values (p_image_id, p_visitor_id, auth.uid())
    on conflict (image_id, visitor_id) do nothing;
  else
    delete from public.portfolio_likes
    where image_id = p_image_id and visitor_id = p_visitor_id;
  end if;
  return p_liked;
end;
$$;

revoke all on function public.get_portfolio_like_state(text[], uuid) from public;
revoke all on function public.set_portfolio_like(text, uuid, boolean) from public;
grant execute on function public.get_portfolio_like_state(text[], uuid) to anon, authenticated, service_role;
grant execute on function public.set_portfolio_like(text, uuid, boolean) to anon, authenticated, service_role;
revoke select, insert, update, delete on public.portfolio_likes from anon, authenticated;

-- Public availability contains only time/resource data, never contact details.
create or replace function public.get_resource_booked_slots_for_date(selected_date date)
returns table (
  booking_time time without time zone,
  duration_hours integer,
  end_time text,
  resource_slug text,
  status text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.booking_time,
    greatest(coalesce(b.duration_hours, 1), 1),
    coalesce(b.end_time, to_char(b.booking_time + greatest(coalesce(b.duration_hours, 1), 1) * interval '1 hour', 'HH24:MI')),
    b.resource_slug,
    b.status
  from public.resource_bookings b
  where b.booking_date = selected_date
    and lower(coalesce(b.status, 'pending')) not in ('cancelled', 'canceled', 'deleted', 'rejected')
  order by b.booking_time;
$$;

revoke all on function public.get_resource_booked_slots_for_date(date) from public;
grant execute on function public.get_resource_booked_slots_for_date(date) to anon, authenticated, service_role;

create or replace function public.get_resource_booking_calendar(selected_start_date date, selected_end_date date)
returns table (
  booking_date date,
  booking_time time without time zone,
  duration_hours integer,
  end_time text,
  resource_slug text,
  status text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.booking_date,
    b.booking_time,
    greatest(coalesce(b.duration_hours, 1), 1),
    coalesce(b.end_time, to_char(b.booking_time + greatest(coalesce(b.duration_hours, 1), 1) * interval '1 hour', 'HH24:MI')),
    b.resource_slug,
    b.status
  from public.resource_bookings b
  where b.booking_date between greatest(selected_start_date, current_date)
    and least(selected_end_date, greatest(selected_start_date, current_date) + 366)
    and lower(coalesce(b.status, 'pending')) not in ('cancelled', 'canceled', 'deleted', 'rejected')
  order by b.booking_date, b.booking_time;
$$;

revoke all on function public.get_resource_booking_calendar(date, date) from public;
grant execute on function public.get_resource_booking_calendar(date, date) to anon, authenticated, service_role;

create or replace function public.create_public_service_booking(payload jsonb)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  new_id uuid := coalesce(nullif(payload->>'id', '')::uuid, gen_random_uuid());
  selected_package uuid := (payload->>'package_id')::uuid;
  selected_option uuid := nullif(payload->>'service_option_id', '')::uuid;
  selected_specialist uuid := nullif(payload->>'specialist_id', '')::uuid;
  selected_date date := (payload->>'booking_date')::date;
  selected_time time := (payload->>'booking_time')::time;
  selected_duration integer := greatest(1, least(coalesce((payload->>'duration_hours')::integer, 1), 12));
  package_price integer;
  package_duration_minutes integer;
  package_is_custom boolean;
  package_currency text;
  allowed_durations integer[];
  capacity_key text;
  addon_total integer := 0;
  safe_addons jsonb := '[]'::jsonb;
  selected_locale text := lower(left(coalesce(nullif(payload->>'language', ''), 'en'), 12));
begin
  if length(trim(coalesce(payload->>'client_name', ''))) not between 2 and 120
     or length(trim(coalesce(payload->>'client_phone', ''))) not between 5 and 40
     or coalesce(payload->>'client_email', '') !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or selected_date < current_date then
    raise exception 'invalid_booking_data' using errcode = '22023';
  end if;

  select price, duration_minutes, is_custom, currency
  into package_price, package_duration_minutes, package_is_custom, package_currency
  from public.packages
  where id = selected_package and is_active = true;
  if package_price is null then
    raise exception 'package_not_available' using errcode = '22023';
  end if;

  if selected_locale !~ '^[a-z]{2,3}(-[a-z]{2})?$' then
    selected_locale := 'en';
  end if;

  if package_is_custom then
    select service_duration_options into allowed_durations
    from public.booking_page_settings where id = 'main';
    if selected_duration <> all(coalesce(allowed_durations, array[1])) then
      raise exception 'duration_not_available' using errcode = '22023';
    end if;
    package_price := package_price * selected_duration;
  else
    selected_duration := greatest(1, least(ceil(coalesce(package_duration_minutes, 60) / 60.0)::integer, 12));
  end if;

  if jsonb_typeof(coalesce(payload->'selected_addons', '[]'::jsonb)) <> 'array'
     or jsonb_array_length(coalesce(payload->'selected_addons', '[]'::jsonb)) > 25 then
    raise exception 'invalid_addons' using errcode = '22023';
  end if;
  select
    coalesce(round(sum(a.price))::integer, 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'id', a.id,
      'title', a.title,
      'price', a.price
    ) order by a.sort_order), '[]'::jsonb)
  into addon_total, safe_addons
  from public.package_addons a
  where a.is_active = true
    and a.id in (
      select (entry->>'id')::uuid
      from jsonb_array_elements(coalesce(payload->'selected_addons', '[]'::jsonb)) entry
    );
  if (selected_option is not null and not exists (
        select 1 from public.service_options where id = selected_option and is_active = true
      )) or (selected_specialist is not null and not exists (
        select 1 from public.team where id = selected_specialist and is_active = true
      )) then
    raise exception 'service_selection_not_available' using errcode = '22023';
  end if;

  capacity_key := coalesce(selected_specialist::text, selected_option::text, selected_package::text);
  perform pg_advisory_xact_lock(hashtextextended('service:' || selected_date || ':' || capacity_key, 0));
  if exists (
    select 1 from public.service_bookings b
    where b.booking_date = selected_date
      and coalesce(b.specialist_id::text, b.service_option_id::text, b.package_id::text) = capacity_key
      and lower(coalesce(b.status, 'pending')) not in ('cancelled', 'canceled', 'deleted', 'rejected')
      and tsrange(selected_date + b.booking_time,
                  selected_date + b.booking_time + greatest(coalesce(b.duration_hours, 1), 1) * interval '1 hour', '[)')
          && tsrange(selected_date + selected_time,
                     selected_date + selected_time + selected_duration * interval '1 hour', '[)')
  ) then
    raise exception 'booking_conflict' using errcode = '23P01';
  end if;

  insert into public.service_bookings (
    id, user_id, client_name, client_phone, client_email, language, package_id, service_option_id,
    specialist_id, booking_date, booking_time, duration_hours, end_time, status,
    total_price, total_amount, selected_addons, notes, payment_status, currency
  ) values (
    new_id, auth.uid(), trim(payload->>'client_name'), trim(payload->>'client_phone'), lower(trim(payload->>'client_email')),
    selected_locale, selected_package, selected_option, selected_specialist, selected_date, selected_time,
    selected_duration, to_char(selected_time + selected_duration * interval '1 hour', 'HH24:MI'), 'pending',
    package_price + addon_total, package_price + addon_total, safe_addons, nullif(trim(payload->>'notes'), ''),
    'pending_payment', upper(coalesce(nullif(package_currency, ''), 'EUR'))
  );
  return new_id;
end;
$$;

-- Universal resource catalog. A deployment can add rooms, equipment, seats,
-- courts or specialists without adding columns or changing application code.
create table public.bookable_resources (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  title text not null,
  description text not null default '',
  image_url text not null default '',
  price_per_hour numeric(10,0) not null default 0 check (price_per_hour >= 0),
  currency text not null default 'EUR' check (currency ~ '^[A-Z]{3}$'),
  open_hour integer not null default 9 check (open_hour between 0 and 23),
  close_hour integer not null default 18 check (close_hour between 1 and 24),
  duration_options integer[] not null default array[1,2,3],
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (open_hour < close_hour),
  check (cardinality(duration_options) between 1 and 24)
);

create table public.resource_page_content (
  id integer primary key default 1 check (id = 1),
  eyebrow text not null default 'Bookable resources',
  title text not null default 'Choose the space, equipment or specialist you need',
  description text not null default 'Browse everything available by time, compare prices and reserve online.',
  primary_cta text not null default 'Check availability',
  catalog_eyebrow text not null default 'Available resources',
  catalog_title text not null default 'Built around the way this business works',
  included_eyebrow text not null default 'Before you book',
  included_title text not null default 'Clear details, pricing and availability',
  included_description text not null default 'Use this section for practical information that applies to every reservation.',
  included_items text not null default E'Live availability\nTransparent hourly pricing\nEmail confirmation',
  process_eyebrow text not null default 'How it works',
  process_title text not null default 'A simple booking flow',
  process_steps text not null default E'Choose a resource\nSelect a date and time\nEnter your contact details\nConfirm and pay',
  faq_eyebrow text not null default 'Questions',
  faq_title text not null default 'Useful information before booking',
  faq_items jsonb not null default '[{"id":"changes","question":"Can I change or cancel a booking?","answer":"The business can publish its cancellation and rescheduling rules in Terms."}]'::jsonb,
  final_title text not null default 'Ready to reserve?',
  final_description text not null default 'Choose a resource and see its available time slots.',
  final_cta text not null default 'Book now',
  hero_image_url text not null default '',
  updated_at timestamptz not null default now()
);

