-- -----------------------------------------------------------------------------

-- Locale-neutral translation store for all new and migrated content modules.
create table if not exists public.content_translations (
  id uuid primary key default gen_random_uuid(),
  entity_type text not null check (entity_type ~ '^[a-z][a-z0-9_]{1,63}$'),
  entity_id text not null,
  field_name text not null check (field_name ~ '^[a-z][a-z0-9_]{1,63}$'),
  locale text not null check (locale ~ '^[a-z]{2,3}(-[a-z]{2})?$'),
  value text not null default '',
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (entity_type, entity_id, field_name, locale)
);

alter table public.content_translations enable row level security;

create policy "Public reads published translations"
on public.content_translations for select to anon, authenticated
using (is_published = true or public.is_admin());

create policy "Admins manage translations"
on public.content_translations to authenticated
using (public.is_admin()) with check (public.is_admin());

create index if not exists content_translations_lookup_idx
on public.content_translations (entity_type, entity_id, locale);

-- Compatibility bridge: old two-locale editors can keep writing their current
-- columns while every write is mirrored into the locale-neutral store.
create or replace function public.sync_legacy_translation_columns()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  row_data jsonb := to_jsonb(new);
  pair record;
  translation_locale text;
  translation_field text;
  translation_entity_id text := coalesce(row_data->>'id', 'main');
begin
  for pair in select key, value from jsonb_each_text(row_data) loop
    if pair.key ~ '_[a-z]{2,3}(-[a-z]{2})?$' then
      translation_locale := lower(substring(pair.key from '_([a-z]{2,3}(-[a-z]{2})?)$'));
      translation_field := regexp_replace(pair.key, '_[a-z]{2,3}(-[a-z]{2})?$', '');
      insert into public.content_translations (
        entity_type, entity_id, field_name, locale, value, is_published, updated_at
      ) values (
        tg_table_name, translation_entity_id, translation_field, translation_locale,
        coalesce(pair.value, ''), true, now()
      )
      on conflict (entity_type, entity_id, field_name, locale)
      do update set value = excluded.value, is_published = excluded.is_published, updated_at = now();
    end if;
  end loop;
  return new;
end;
$$;

-- Backfill every existing legacy locale column without maintaining a hand-written list.
do $$
declare
  column_row record;
begin
  for column_row in
    select c.table_name, c.column_name,
           regexp_replace(c.column_name, '_[a-z]{2,3}(-[a-z]{2})?$', '') as field_name,
           lower(substring(c.column_name from '_([a-z]{2,3}(-[a-z]{2})?)$')) as locale
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.column_name ~ '_[a-z]{2,3}(-[a-z]{2})?$'
      and exists (
        select 1 from information_schema.columns idc
        where idc.table_schema = c.table_schema and idc.table_name = c.table_name and idc.column_name = 'id'
      )
  loop
    execute format(
      'insert into public.content_translations (entity_type, entity_id, field_name, locale, value, is_published)
       select %L, id::text, %L, %L, coalesce(%I::text, ''''), true from public.%I
       where %I is not null
       on conflict (entity_type, entity_id, field_name, locale)
       do update set value = excluded.value, is_published = true, updated_at = now()',
      column_row.table_name, column_row.field_name, column_row.locale,
      column_row.column_name, column_row.table_name, column_row.column_name
    );
  end loop;
end;
$$;

-- Install the compatibility trigger on each table that still has locale columns.
do $$
declare
  table_row record;
begin
  for table_row in
    select distinct c.table_name
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.column_name ~ '_[a-z]{2,3}(-[a-z]{2})?$'
      and c.table_name <> 'content_translations'
  loop
    execute format('drop trigger if exists sync_legacy_translations on public.%I', table_row.table_name);
    execute format(
      'create trigger sync_legacy_translations after insert or update on public.%I
       for each row execute function public.sync_legacy_translation_columns()',
      table_row.table_name
    );
  end loop;
end;
$$;

create or replace function public.get_entity_translations(
  p_entity_type text,
  p_entity_id text
)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    jsonb_object_agg(field_name, locale_values),
    '{}'::jsonb
  )
  from (
    select field_name, jsonb_object_agg(locale, value order by locale) as locale_values
    from public.content_translations
    where entity_type = p_entity_type and entity_id = p_entity_id and is_published = true
    group by field_name
  ) translated_fields;
$$;

revoke all on function public.get_entity_translations(text, text) from public;
grant execute on function public.get_entity_translations(text, text) to anon, authenticated, service_role;


