-- Reusable admin booking and promotion modules.

alter table public.resource_bookings
  add column if not exists booking_source text not null default 'public'
    check (booking_source in ('public', 'admin')),
  add column if not exists client_instagram text,
  add column if not exists promo_code text,
  add column if not exists discount_amount integer not null default 0
    check (discount_amount >= 0);

create table if not exists public.promo_codes (
  id uuid primary key default gen_random_uuid(),
  code text not null,
  description text not null default '',
  discount_type text not null check (discount_type in ('percent', 'fixed', 'free_hour')),
  discount_value integer not null default 0 check (discount_value >= 0),
  minimum_hours integer not null default 1 check (minimum_hours between 1 and 24),
  starts_at timestamptz,
  ends_at timestamptz,
  max_uses integer check (max_uses is null or max_uses > 0),
  uses_count integer not null default 0 check (uses_count >= 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint promo_codes_code_format check (code ~ '^[A-Z0-9][A-Z0-9_-]{2,31}$')
);

create unique index if not exists promo_codes_code_upper_unique
  on public.promo_codes (upper(code));

alter table public.promo_codes enable row level security;

create policy "Admins manage promo codes"
on public.promo_codes to authenticated
using (public.is_admin()) with check (public.is_admin());

revoke all on public.promo_codes from anon, authenticated;
grant select, insert, update, delete on public.promo_codes to authenticated;

create or replace function public.calculate_resource_promo(
  p_code text,
  p_subtotal integer,
  p_total_hours integer,
  p_lowest_hour_price integer,
  p_booking_date date default current_date
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  promo public.promo_codes%rowtype;
  normalized_code text := upper(trim(coalesce(p_code, '')));
  discount integer := 0;
begin
  if normalized_code = '' then
    return jsonb_build_object('valid', false, 'code', null, 'discount', 0, 'reason', 'empty');
  end if;

  select * into promo
  from public.promo_codes
  where upper(code) = normalized_code
    and is_active = true
    and (starts_at is null or starts_at <= p_booking_date + time '23:59:59')
    and (ends_at is null or ends_at >= p_booking_date)
    and (max_uses is null or uses_count < max_uses);

  if promo.id is null then
    return jsonb_build_object('valid', false, 'code', normalized_code, 'discount', 0, 'reason', 'not_available');
  end if;
  if p_total_hours < promo.minimum_hours then
    return jsonb_build_object('valid', false, 'code', normalized_code, 'discount', 0, 'reason', 'minimum_hours');
  end if;

  discount := case promo.discount_type
    when 'percent' then round(p_subtotal * least(promo.discount_value, 100) / 100.0)::integer
    when 'fixed' then promo.discount_value
    when 'free_hour' then greatest(p_lowest_hour_price, 0)
    else 0
  end;
  discount := greatest(0, least(discount, p_subtotal));

  return jsonb_build_object(
    'valid', true,
    'code', normalized_code,
    'discount', discount,
    'discount_type', promo.discount_type,
    'discount_value', promo.discount_value,
    'description', promo.description
  );
end;
$$;

revoke all on function public.calculate_resource_promo(text, integer, integer, integer, date) from public;
grant execute on function public.calculate_resource_promo(text, integer, integer, integer, date)
  to anon, authenticated, service_role;

create or replace function public.preview_resource_promo(payload jsonb)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare item jsonb; resource_row public.bookable_resources%rowtype; item_hours integer;
  subtotal integer := 0; total_hours integer := 0; lowest_price integer := null;
begin
  if jsonb_typeof(payload->'items') <> 'array' or jsonb_array_length(payload->'items') not between 1 and 5 then
    raise exception 'invalid_items' using errcode = '22023';
  end if;
  for item in select value from jsonb_array_elements(payload->'items') loop
    select * into resource_row from public.bookable_resources where slug = item->>'resource_slug' and is_active = true;
    if resource_row.id is null then raise exception 'invalid_resource' using errcode = '22023'; end if;
    item_hours := coalesce((item->>'duration_hours')::integer, 1);
    if not (item_hours = any(resource_row.duration_options)) then raise exception 'invalid_duration' using errcode = '22023'; end if;
    subtotal := subtotal + resource_row.price_per_hour::integer * item_hours;
    total_hours := total_hours + item_hours;
    lowest_price := least(coalesce(lowest_price, resource_row.price_per_hour::integer), resource_row.price_per_hour::integer);
  end loop;
  return public.calculate_resource_promo(payload->>'promo_code', subtotal, total_hours, coalesce(lowest_price, 0),
    coalesce(nullif(payload->>'booking_date', '')::date, current_date)) || jsonb_build_object('subtotal', subtotal);
end;
$$;

create or replace function public.create_admin_resource_booking(p_order_id text, payload jsonb)
returns text language plpgsql security definer set search_path = public as $$
declare selected_date date := (payload->>'booking_date')::date; item jsonb := payload->'items'->0;
  resource_row public.bookable_resources%rowtype; selected_time time; selected_duration integer; row_total integer;
begin
  if not public.is_admin() then raise exception 'admin_required' using errcode = '42501'; end if;
  if jsonb_typeof(payload->'items') <> 'array' or jsonb_array_length(payload->'items') <> 1
     or length(trim(coalesce(payload->>'client_name', ''))) not between 2 and 120
     or length(trim(coalesce(payload->>'client_phone', ''))) not between 5 and 40 or selected_date < current_date then
    raise exception 'invalid_booking_data' using errcode = '22023';
  end if;
  select * into resource_row from public.bookable_resources where slug = item->>'resource_slug';
  if resource_row.id is null then raise exception 'invalid_resource' using errcode = '22023'; end if;
  selected_time := (item->>'booking_time')::time;
  selected_duration := coalesce((item->>'duration_hours')::integer, 1);
  if not (selected_duration = any(resource_row.duration_options))
     or extract(hour from selected_time) < resource_row.open_hour
     or extract(hour from selected_time) + selected_duration > resource_row.close_hour then
    raise exception 'invalid_resource_time' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('resource:' || selected_date || ':' || resource_row.slug, 0));
  if exists (select 1 from public.resource_bookings b where b.booking_date = selected_date
      and b.resource_slug = resource_row.slug
      and lower(coalesce(b.status, 'pending')) not in ('cancelled', 'canceled', 'deleted', 'rejected')
      and tsrange(selected_date + b.booking_time, selected_date + b.booking_time + greatest(coalesce(b.duration_hours, 1), 1) * interval '1 hour', '[)')
          && tsrange(selected_date + selected_time, selected_date + selected_time + selected_duration * interval '1 hour', '[)')) then
    raise exception 'booking_conflict' using errcode = '23P01';
  end if;
  row_total := resource_row.price_per_hour::integer * selected_duration;
  insert into public.resource_bookings (resource_order_id, client_name, client_phone, client_email, client_instagram,
    language, booking_date, booking_time, end_time, duration_hours, resource_slug, price_per_hour, total_price,
    status, notes, payment_status, currency, booking_source)
  values (p_order_id, trim(payload->>'client_name'), trim(payload->>'client_phone'), nullif(lower(trim(payload->>'client_email')), ''),
    nullif(trim(payload->>'client_instagram'), ''), left(coalesce(nullif(payload->>'language', ''), 'en'), 12),
    selected_date, selected_time, to_char(selected_time + selected_duration * interval '1 hour', 'HH24:MI'),
    selected_duration, resource_row.slug, resource_row.price_per_hour, row_total, 'pending', nullif(trim(payload->>'notes'), ''),
    coalesce(nullif(payload->>'payment_status', ''), 'not_required'), resource_row.currency, 'admin');
  return p_order_id;
end;
$$;

create or replace function public.admin_create_manual_resource_booking(payload jsonb)
returns text language plpgsql security definer set search_path = public as $$
declare order_id text := 'manual_' || replace(gen_random_uuid()::text, '-', '');
begin return public.create_admin_resource_booking(order_id, payload); end;
$$;

create or replace function public.admin_replace_manual_resource_booking(p_order_id text, payload jsonb)
returns text language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'admin_required' using errcode = '42501'; end if;
  if not exists (select 1 from public.resource_bookings where resource_order_id = p_order_id and booking_source = 'admin') then
    raise exception 'manual_booking_not_found' using errcode = 'P0002';
  end if;
  delete from public.resource_bookings where resource_order_id = p_order_id and booking_source = 'admin';
  return public.create_admin_resource_booking(p_order_id, payload);
end;
$$;

revoke all on function public.preview_resource_promo(jsonb) from public;
grant execute on function public.preview_resource_promo(jsonb) to anon, authenticated, service_role;
revoke all on function public.create_admin_resource_booking(text, jsonb) from public;
revoke all on function public.admin_create_manual_resource_booking(jsonb) from public;
revoke all on function public.admin_replace_manual_resource_booking(text, jsonb) from public;
grant execute on function public.admin_create_manual_resource_booking(jsonb) to authenticated, service_role;
grant execute on function public.admin_replace_manual_resource_booking(text, jsonb) to authenticated, service_role;

create or replace function public.create_public_resource_booking(payload jsonb)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  order_id text := coalesce(nullif(payload->>'order_id', ''), 'resource_' || replace(gen_random_uuid()::text, '-', ''));
  selected_date date := (payload->>'booking_date')::date;
  item jsonb;
  resource_row public.bookable_resources%rowtype;
  selected_time time;
  selected_duration integer;
  row_total integer;
  promo jsonb;
  discount integer := 0;
begin
  if not coalesce((select resource_booking_enabled from public.booking_page_settings where id = 'main'), false) then
    raise exception 'resource_booking_disabled' using errcode = '22023';
  end if;
  if jsonb_typeof(payload->'items') <> 'array' or jsonb_array_length(payload->'items') <> 1
     or length(trim(coalesce(payload->>'client_name', ''))) not between 2 and 120
     or length(trim(coalesce(payload->>'client_phone', ''))) not between 5 and 40
     or coalesce(payload->>'client_email', '') !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or selected_date < current_date then
    raise exception 'invalid_booking_data' using errcode = '22023';
  end if;

  item := payload->'items'->0;
  select * into resource_row from public.bookable_resources
  where slug = item->>'resource_slug' and is_active = true;
  if resource_row.id is null then
    raise exception 'invalid_resource' using errcode = '22023';
  end if;

  selected_time := (item->>'booking_time')::time;
  selected_duration := coalesce((item->>'duration_hours')::integer, 1);
  if not (selected_duration = any(resource_row.duration_options))
     or extract(hour from selected_time) < resource_row.open_hour
     or extract(hour from selected_time) + selected_duration > resource_row.close_hour then
    raise exception 'invalid_resource_time' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('resource:' || selected_date || ':' || resource_row.slug, 0));
  if exists (
    select 1 from public.resource_bookings b
    where b.booking_date = selected_date
      and b.resource_slug = resource_row.slug
      and lower(coalesce(b.status, 'pending')) not in ('cancelled', 'canceled', 'deleted', 'rejected')
      and tsrange(selected_date + b.booking_time,
                  selected_date + b.booking_time + greatest(coalesce(b.duration_hours, 1), 1) * interval '1 hour', '[)')
          && tsrange(selected_date + selected_time,
                     selected_date + selected_time + selected_duration * interval '1 hour', '[)')
  ) then
    raise exception 'booking_conflict' using errcode = '23P01';
  end if;

  row_total := resource_row.price_per_hour::integer * selected_duration;
  promo := public.calculate_resource_promo(
    payload->>'promo_code', row_total, selected_duration,
    resource_row.price_per_hour::integer, selected_date
  );
  if nullif(trim(coalesce(payload->>'promo_code', '')), '') is not null
     and not coalesce((promo->>'valid')::boolean, false) then
    raise exception 'promo_not_available' using errcode = '22023';
  end if;
  if coalesce((promo->>'valid')::boolean, false) then
    discount := coalesce((promo->>'discount')::integer, 0);
  end if;
  insert into public.resource_bookings (
    resource_order_id, client_name, client_phone, client_email, language, booking_date,
    booking_time, end_time, duration_hours, resource_slug, price_per_hour, total_price,
    status, notes, payment_status, currency, booking_source, promo_code, discount_amount
  ) values (
    order_id, trim(payload->>'client_name'), trim(payload->>'client_phone'), lower(trim(payload->>'client_email')),
    left(coalesce(nullif(payload->>'language', ''), 'en'), 12), selected_date, selected_time,
    to_char(selected_time + selected_duration * interval '1 hour', 'HH24:MI'), selected_duration,
    resource_row.slug, resource_row.price_per_hour, row_total - discount, 'pending', nullif(trim(payload->>'notes'), ''),
    'pending_payment', resource_row.currency, 'public',
    case when coalesce((promo->>'valid')::boolean, false) then promo->>'code' else null end, discount
  );
  if coalesce((promo->>'valid')::boolean, false) then
    update public.promo_codes set uses_count = uses_count + 1, updated_at = now()
    where upper(code) = promo->>'code';
  end if;
  return order_id;
end;
$$;

revoke all on function public.create_public_resource_booking(jsonb) from public;
grant execute on function public.create_public_resource_booking(jsonb) to anon, authenticated, service_role;


